package mrpapermoon.whisper.contacts.diimport android.content.Contextimport androidx.room.Roomimport dagger.Moduleimport dagger.Providesimport dagger.hilt.InstallInimport dagger.hilt.android.qualifiers.ApplicationContextimport dagger.hilt.components.SingletonComponentimport mrpapermoon.whisper.contacts.db.ContactDaoimport mrpapermoon.whisper.contacts.db.ContactsDatabaseimport javax.inject.Singleton@Module@InstallIn(SingletonComponent::class)object ContactsModule {	@Provides	@Singleton	fun provideContactsDatabase(		@ApplicationContext context: Context	): ContactsDatabase {		return Room.databaseBuilder(			context,			ContactsDatabase::class.java,			"contacts_database"		).build()	}	@Provides	fun provideContactDao(database: ContactsDatabase): ContactDao = database.contactDao()}